  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',pid,'receiptID',gen_random_uuid(),'memberEpochID',epoch,'agreementID',agreement->>'agreementID','planID',plan_one,'planRevision',1,'sourceID',receipt_source,'revision',3,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','outcome','unknown','protectionEvidence','unknown')); raise exception 'source-tombstoned v2 replay accepted'; exception when raise_exception then if sqlerrm<>'shared_history_deleted' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',pid,'receiptID',gen_random_uuid(),'memberEpochID',epoch,'agreementID',agreement->>'agreementID','sourceID',gen_random_uuid(),'revision',3,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','actualStart',(d+time '21:35:00.100')::timestamptz,'outcome','unknown','protectionEvidence','unknown')); raise exception 'fractional receipt timestamp accepted'; exception when raise_exception then if sqlerrm<>'invalid_receipt_chronology' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',pid,'receiptID',gen_random_uuid(),'memberEpochID',epoch,'agreementID',agreement->>'agreementID','planID',plan_one,'sourceID',gen_random_uuid(),'revision',1,'nightEndingDate',d,'timeZoneIdentifier','UTC','outcome','unknown','protectionEvidence','unknown')); raise exception 'half plan binding accepted'; exception when raise_exception then if sqlerrm<>'invalid_plan_binding' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',pid,'planID',gen_random_uuid(),'memberEpochID',epoch,'agreementID',agreement->>'agreementID','revision',3,'nightEndingDate',d,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+time '21:30')::timestamptz,'intendedBedtime',(d+time '22:00')::timestamptz,'intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb,'bundleID','forbidden')); raise exception 'exact app field accepted'; exception when raise_exception then if sqlerrm<>'invalid_shared_night_payload' then raise; end if; end;
  for i in 3..102 loop
    plan_id:=('95000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid;
    perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',pid,'planID',plan_id,'memberEpochID',epoch,'agreementID',agreement->>'agreementID','revision',i,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+1+time '00:30')::timestamptz,'intendedBedtime',(d+1+time '01:00')::timestamptz,'intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb));
  end loop;
  state:=public.night_flock_v4_state(member_id,'sharedNights',pid,null); cursor:=state->>'sharedNightsNextCursor';
  -- `sharedNights` is a 100-event page. Receipts consume event slots and may
  -- pull their frozen supporting plan into the response, so presentation rows
  -- are between 100 and 200 rather than necessarily 100 plans.
  if cursor is null
    or jsonb_array_length(state->'sharedNightPlans')+jsonb_array_length(state->'sharedNightReceipts')<100
    or jsonb_array_length(state->'sharedNightPlans')+jsonb_array_length(state->'sharedNightReceipts')>200
  then raise exception 'v2 first page was not bounded/cursorized'; end if;
  update private.night_flock_v4_shared_night_plans set planned_wind_down_start=now()-interval '5 minutes' where id=plan_id;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',pid,'planID',gen_random_uuid(),'memberEpochID',epoch,'agreementID',agreement->>'agreementID','revision',103,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+1+time '00:30')::timestamptz,'intendedBedtime',(d+1+time '01:00')::timestamptz,'intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb)); raise exception 'late revision bypassed stored plan freeze'; exception when raise_exception then if sqlerrm<>'shared_night_plan_frozen' then raise; end if; end;
  perform public.night_flock_v4_state(member_id,'sharedNights',pid,cursor);

  -- A plan privacy cancellation is a server-side receipt fence, not merely a
  -- state-projection hide. Keep the already accepted receipt archived, but
  -- reject delayed plan-bound and planless receipts from any source/revision.
  privacy_pid:=(public.night_flock_v4_command(privacy_host_id,jsonb_build_object('command','createParty','name','V2 privacy receipt fence','timeZoneIdentifier','UTC'))->>'resolvedPartyID')::uuid;
  insert into private.night_flock_v4_memberships(party_id,user_id,role) values(privacy_pid,member_id,'member');
  privacy_agreement:=public.night_flock_v4_command(member_id,jsonb_build_object('command','acceptSharedHabitsAgreement','partyID',privacy_pid,'agreementVersion',2,'timeZoneIdentifier','UTC'));
  privacy_epoch:=(privacy_agreement->>'memberEpochID')::uuid;
  update private.night_flock_v4_shared_habits_agreements set accepted_at=d::timestamptz where id=(privacy_agreement->>'agreementID')::uuid;
  privacy_plan:=gen_random_uuid(); privacy_receipt:=gen_random_uuid();
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',privacy_pid,'planID',privacy_plan,'memberEpochID',privacy_epoch,'agreementID',privacy_agreement->>'agreementID','revision',1,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+1+time '00:30')::timestamptz,'intendedBedtime',(d+1+time '01:00')::timestamptz,'intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb));
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',privacy_pid,'receiptID',privacy_receipt,'memberEpochID',privacy_epoch,'agreementID',privacy_agreement->>'agreementID','planID',privacy_plan,'planRevision',1,'sourceID',gen_random_uuid(),'revision',1,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','actualStart',(d+time '21:35')::timestamptz,'terminalAt',(d+time '22:00')::timestamptz,'outcome','partlyCompleted','windDownMinutes',25,'protectionEvidence','unknown'));
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',privacy_pid,'memberEpochID',privacy_epoch,'agreementID',privacy_agreement->>'agreementID','revision',2,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','cancellationAuthority','privacy'));
  select revision into archive_before from private.night_flock_v4_parties where id=privacy_pid;
  if not exists(select 1 from private.night_flock_v4_shared_night_receipts r where r.id=privacy_receipt) then raise exception 'privacy cancellation deleted already archived factual receipt'; end if;
  state:=public.night_flock_v4_state(member_id,'sharedNights',privacy_pid,null);
  if exists(select 1 from jsonb_array_elements(state->'sharedNightReceipts') value where (value->>'receiptID')::uuid=privacy_receipt) then raise exception 'privacy cancellation left historical receipt visible'; end if;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',privacy_pid,'receiptID',gen_random_uuid(),'memberEpochID',privacy_epoch,'agreementID',privacy_agreement->>'agreementID','planID',privacy_plan,'planRevision',1,'sourceID',gen_random_uuid(),'revision',99,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','actualStart',(d+time '21:35')::timestamptz,'terminalAt',(d+time '22:05')::timestamptz,'outcome','completed','windDownMinutes',30,'protectionEvidence','observed')); raise exception 'privacy-cancelled plan-bound receipt accepted'; exception when raise_exception then if sqlerrm<>'shared_night_plan_cancelled' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',privacy_pid,'receiptID',gen_random_uuid(),'memberEpochID',privacy_epoch,'agreementID',privacy_agreement->>'agreementID','sourceID',gen_random_uuid(),'revision',100,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','actualStart',(d+time '21:35')::timestamptz,'terminalAt',(d+time '22:05')::timestamptz,'outcome','completed','windDownMinutes',30,'protectionEvidence','observed')); raise exception 'privacy-cancelled planless receipt accepted'; exception when raise_exception then if sqlerrm<>'shared_night_plan_cancelled' then raise; end if; end;
  if (select revision from private.night_flock_v4_parties where id=privacy_pid)<>archive_before or (select count(*) from private.night_flock_v4_shared_night_receipts where party_id=privacy_pid)<>1 then raise exception 'privacy receipt rejection churned archive or stored delayed replay'; end if;

  -- Schedule cancellation is revision-ordered and reversible; a privacy
  -- cancellation upgrades it exactly once and stays terminal.
  ordering_pid:=(public.night_flock_v4_command(privacy_host_id,jsonb_build_object('command','createParty','name','V2 cancellation ordering','timeZoneIdentifier','UTC'))->>'resolvedPartyID')::uuid;
  insert into private.night_flock_v4_memberships(party_id,user_id,role) values(ordering_pid,member_id,'member');
  ordering_agreement:=public.night_flock_v4_command(member_id,jsonb_build_object('command','acceptSharedHabitsAgreement','partyID',ordering_pid,'agreementVersion',2,'timeZoneIdentifier','UTC'));
  ordering_epoch:=(ordering_agreement->>'memberEpochID')::uuid;
  ordering_plan:=gen_random_uuid();
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',ordering_pid,'planID',ordering_plan,'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',3,'nightEndingDate',d+2,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+1+time '21:30')::timestamptz,'intendedBedtime',(d+1+time '22:00')::timestamptz,'intendedWakeTime',(d+2+time '07:00')::timestamptz,'morningQuietEnd',(d+2+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb));
  select revision into archive_before from private.night_flock_v4_parties where id=ordering_pid;
  if not coalesce((public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',ordering_pid,'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',2,'nightEndingDate',d+2,'timeZoneIdentifier','UTC','cancellationAuthority','schedule'))->>'staleRevision')::boolean,false)
     or (select revision from private.night_flock_v4_parties where id=ordering_pid)<>archive_before
     or exists(select 1 from private.night_flock_v4_shared_night_plan_tombstones where party_id=ordering_pid and member_epoch_id=ordering_epoch and night_ending_date=d+2)
  then raise exception 'delayed schedule cancellation hid an equal-or-newer plan'; end if;
  state:=public.night_flock_v4_state(member_id,'sharedNights',ordering_pid,null);
  if not exists(select 1 from jsonb_array_elements(state->'sharedNightPlans') value where (value->>'planID')::uuid=ordering_plan) then raise exception 'delayed schedule cancellation hid the visible plan'; end if;
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',ordering_pid,'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',4,'nightEndingDate',d+2,'timeZoneIdentifier','UTC','cancellationAuthority','schedule'));
