  if exists(select 1 from private.night_flock_v4_shared_night_plan_tombstones where party_id=ordering_pid and member_epoch_id=ordering_epoch and night_ending_date=d+2) then raise exception 'newer plan did not revive schedule cancellation'; end if;

  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',ordering_pid,'planID',gen_random_uuid(),'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',3,'nightEndingDate',d+3,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+2+time '21:30')::timestamptz,'intendedBedtime',(d+2+time '22:00')::timestamptz,'intendedWakeTime',(d+3+time '07:00')::timestamptz,'morningQuietEnd',(d+3+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb));
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',ordering_pid,'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',4,'nightEndingDate',d+3,'timeZoneIdentifier','UTC','cancellationAuthority','schedule'));
  select revision into archive_before from private.night_flock_v4_parties where id=ordering_pid;
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',ordering_pid,'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',2,'nightEndingDate',d+3,'timeZoneIdentifier','UTC','cancellationAuthority','privacy'));
  if not exists(select 1 from private.night_flock_v4_shared_night_plan_tombstones where party_id=ordering_pid and member_epoch_id=ordering_epoch and night_ending_date=d+3 and revision=4 and cancellation_authority='privacy')
     or (select revision from private.night_flock_v4_parties where id=ordering_pid)<>archive_before+1
  then raise exception 'privacy cancellation did not upgrade schedule authority once'; end if;
  select revision into archive_before from private.night_flock_v4_parties where id=ordering_pid;
  if not coalesce((public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',ordering_pid,'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',2,'nightEndingDate',d+3,'timeZoneIdentifier','UTC','cancellationAuthority','privacy'))->>'staleRevision')::boolean,false)
     or (select revision from private.night_flock_v4_parties where id=ordering_pid)<>archive_before
  then raise exception 'repeated privacy cancellation churned archive'; end if;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',ordering_pid,'planID',gen_random_uuid(),'memberEpochID',ordering_epoch,'agreementID',ordering_agreement->>'agreementID','revision',5,'nightEndingDate',d+3,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+2+time '21:30')::timestamptz,'intendedBedtime',(d+2+time '22:00')::timestamptz,'intendedWakeTime',(d+3+time '07:00')::timestamptz,'morningQuietEnd',(d+3+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb)); raise exception 'privacy tombstone allowed later plan revival'; exception when raise_exception then if sqlerrm<>'shared_night_plan_cancelled' then raise; end if; end;

  -- A schedule edit cannot hide a plan after its frozen start, while an
  -- explicit privacy choice still may. Incoming backdated plan revisions are
  -- rejected even when the stored plan itself remains future/unfrozen.
  freeze_pid:=(public.night_flock_v4_command(privacy_host_id,jsonb_build_object('command','createParty','name','V2 frozen cancellation','timeZoneIdentifier','UTC'))->>'resolvedPartyID')::uuid;
  insert into private.night_flock_v4_memberships(party_id,user_id,role) values(freeze_pid,member_id,'member');
  freeze_agreement:=public.night_flock_v4_command(member_id,jsonb_build_object('command','acceptSharedHabitsAgreement','partyID',freeze_pid,'agreementVersion',2,'timeZoneIdentifier','UTC'));
  freeze_epoch:=(freeze_agreement->>'memberEpochID')::uuid;
  freeze_plan:=gen_random_uuid();
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',freeze_pid,'planID',freeze_plan,'memberEpochID',freeze_epoch,'agreementID',freeze_agreement->>'agreementID','revision',1,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+1+time '00:30')::timestamptz,'intendedBedtime',(d+1+time '01:00')::timestamptz,'intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb));
  select revision into archive_before from private.night_flock_v4_parties where id=freeze_pid;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',freeze_pid,'planID',gen_random_uuid(),'memberEpochID',freeze_epoch,'agreementID',freeze_agreement->>'agreementID','revision',2,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','plannedWindDownStart',date_trunc('hour',now()),'intendedBedtime',date_trunc('hour',now())+interval '30 minutes','intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb)); raise exception 'backdated incoming revision superseded future plan'; exception when raise_exception then if sqlerrm<>'shared_night_plan_frozen' then raise; end if; end;
  if (select revision from private.night_flock_v4_parties where id=freeze_pid)<>archive_before or not exists(select 1 from private.night_flock_v4_shared_night_plans where id=freeze_plan and superseded_at is null) then raise exception 'backdated plan rejection churned archive or superseded future plan'; end if;
  update private.night_flock_v4_shared_night_plans set planned_wind_down_start=now()-interval '5 minutes' where id=freeze_plan;
  select revision into archive_before from private.night_flock_v4_parties where id=freeze_pid;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',freeze_pid,'memberEpochID',freeze_epoch,'agreementID',freeze_agreement->>'agreementID','revision',3,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','cancellationAuthority','schedule')); raise exception 'schedule cancellation hid frozen plan'; exception when raise_exception then if sqlerrm<>'shared_night_plan_frozen' then raise; end if; end;
  if (select revision from private.night_flock_v4_parties where id=freeze_pid)<>archive_before or exists(select 1 from private.night_flock_v4_shared_night_plan_tombstones where party_id=freeze_pid and member_epoch_id=freeze_epoch and night_ending_date=d+1) then raise exception 'frozen schedule cancellation churned archive or wrote tombstone'; end if;
  state:=public.night_flock_v4_state(member_id,'sharedNights',freeze_pid,null);
  if not exists(select 1 from jsonb_array_elements(state->'sharedNightPlans') value where (value->>'planID')::uuid=freeze_plan) then raise exception 'frozen schedule cancellation hid visible plan'; end if;
  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','cancelSharedNightPlan','partyID',freeze_pid,'memberEpochID',freeze_epoch,'agreementID',freeze_agreement->>'agreementID','revision',3,'nightEndingDate',d+1,'timeZoneIdentifier','UTC','cancellationAuthority','privacy'));
  if not exists(select 1 from private.night_flock_v4_shared_night_plan_tombstones where party_id=freeze_pid and member_epoch_id=freeze_epoch and night_ending_date=d+1 and cancellation_authority='privacy') then raise exception 'explicit privacy cancellation did not fence frozen plan'; end if;

  perform public.night_flock_v4_command(member_id,jsonb_build_object('command','deleteSharedHabitHistory','partyID',pid,'allSources',true));
  begin perform public.night_flock_v4_state(member_id,'sharedNights',pid,cursor); raise exception 'v2 deletion left cursor valid'; exception when raise_exception then if sqlerrm<>'stale_revision' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',pid,'planID',gen_random_uuid(),'memberEpochID',epoch,'agreementID',agreement->>'agreementID','revision',103,'nightEndingDate',d,'timeZoneIdentifier','UTC','plannedWindDownStart',(d+time '21:30')::timestamptz,'intendedBedtime',(d+time '22:00')::timestamptz,'intendedWakeTime',(d+1+time '07:00')::timestamptz,'morningQuietEnd',(d+1+time '07:30')::timestamptz,'beforeBedMinutes',30,'afterWakingMinutes',30,'eveningSuggestionIDs','[]'::jsonb,'morningSuggestionIDs','[]'::jsonb)); raise exception 'tombstoned v2 replay accepted'; exception when raise_exception then if sqlerrm<>'shared_history_deleted' then raise; end if; end;
  update auth.users set is_anonymous=false,raw_app_meta_data='{"provider":"email","providers":["email"]}'::jsonb where id=member_id;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','acceptSharedHabitsAgreement','partyID',pid,'agreementVersion',2,'timeZoneIdentifier','UTC')); raise exception 'unlinked v2 agreement accepted'; exception when raise_exception then if sqlerrm<>'Apple-linked account required' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightPlan','partyID',pid)); raise exception 'unlinked v2 plan accepted'; exception when raise_exception then if sqlerrm<>'Apple-linked account required' then raise; end if; end;
  begin perform public.night_flock_v4_command(member_id,jsonb_build_object('command','publishSharedNightReceipt','partyID',pid)); raise exception 'unlinked v2 receipt accepted'; exception when raise_exception then if sqlerrm<>'Apple-linked account required' then raise; end if; end;
end $$;

